#include <bits/stdc++.h>
using namespace std;
int main() {
    int k;
    cin >> k;
    vector<int> coins(k);
    for (auto& c : coins) cin >> c;
    int amount;
    cin >> amount;
    const int INF = INT_MAX / 2;
    vector<int> fewest(amount + 1, INF);
    fewest[0] = 0;
    for (int x = 1; x <= amount; x++)
        for (int c : coins)
            if (c <= x) fewest[x] = min(fewest[x], fewest[x - c] + 1);
    cout << (fewest[amount] >= INF ? -1 : fewest[amount]) << "\n";
    return 0;
}

