#include <bits/stdc++.h>
using namespace std;
int main() {
    const long long MOD = 1000000007;
    int R, C;
    cin >> R >> C;
    vector<string> g(R);
    for (auto& row : g) cin >> row;
    vector<long long> ways(C, 0);
    ways[0] = g[0][0] == '.' ? 1 : 0;
    for (int r = 0; r < R; r++)
        for (int c = 0; c < C; c++) {
            if (g[r][c] == '#') ways[c] = 0;
            else if (c > 0) ways[c] = (ways[c] + ways[c - 1]) % MOD;
        }
    cout << ways[C - 1] << "\n";
    return 0;
}

